        [Header("Button Colors")]
        [SerializeField]
        private Color buttonColorMinigame = Color.yellow;
        [SerializeField]
        private Color buttonColorLocked = Color.gray;
        [SerializeField]
        private Color buttonColorBoss = Color.red;
        [SerializeField]
        private Color buttonColorEndless = Color.magenta;
